{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.capsule_nu_ru_daily AS WITH capsule_skus AS ( SELECT DISTINCT UPPER(TRIM(SKU)) AS SKU, TRIM(COLLECTION) AS CAPSULE FROM snitch_db.maplemonk.collection_sku_mapped_sheet1 WHERE SKU IS NOT NULL AND COLLECTION IS NOT NULL ), online_base AS ( SELECT DISTINCT f.CUSTOMER_ID, UPPER(TRIM(f.SKU_GROUP)) AS SKU, TO_DATE(f.ORDER_TIMESTAMP) AS ORDER_DATE, CASE WHEN UPPER(TRIM(f.NEW_CUSTOMER_FLAG)) = \'NEW\' THEN \'NU\' WHEN UPPER(TRIM(f.NEW_CUSTOMER_FLAG)) = \'REPEATED\' THEN \'RU\' END AS CUSTOMER_TYPE FROM snitch_db.maplemonk.fact_items_snitch f WHERE f.CUSTOMER_ID IS NOT NULL AND f.ORDER_TIMESTAMP IS NOT NULL AND UPPER(TRIM(f.NEW_CUSTOMER_FLAG)) IN (\'NEW\', \'REPEATED\') ), online_classified AS ( SELECT b.CUSTOMER_ID, b.SKU, b.ORDER_DATE, b.CUSTOMER_TYPE, c.CAPSULE FROM online_base b LEFT JOIN capsule_skus c ON b.SKU = c.SKU ), offline_base AS ( SELECT DISTINCT RIGHT( REGEXP_REPLACE( f.PHONE, \'[^0-9]\', \'\' ), 10 ) AS CUSTOMER_ID, UPPER(TRIM(f.SKU_GROUP)) AS SKU, TO_DATE(f.ORDER_DATE) AS ORDER_DATE, CASE WHEN a.PHONE_NO IS NULL THEN NULL WHEN CAST( a.FIRST_ORDER_DATE AS DATE ) = TO_DATE(f.ORDER_DATE) THEN \'NU\' ELSE \'RU\' END AS CUSTOMER_TYPE FROM snitch_db.maplemonk.store_fact_items_offline f LEFT JOIN snitch_db.maplemonk.customer_acq_date_channel a ON RIGHT( REGEXP_REPLACE( f.PHONE, \'[^0-9]\', \'\' ), 10 ) = RIGHT( REGEXP_REPLACE( a.PHONE_NO, \'[^0-9]\', \'\' ), 10 ) WHERE f.PHONE IS NOT NULL AND f.ORDER_DATE IS NOT NULL ), offline_classified AS ( SELECT b.CUSTOMER_ID, b.SKU, b.ORDER_DATE, b.CUSTOMER_TYPE, c.CAPSULE FROM offline_base b INNER JOIN capsule_skus c ON b.SKU = c.SKU WHERE b.CUSTOMER_TYPE IS NOT NULL ), platform_daily AS ( SELECT ORDER_DATE, COUNT(DISTINCT CASE WHEN CUSTOMER_TYPE = \'NU\' THEN CUSTOMER_ID END) AS PLATFORM_NU, COUNT(DISTINCT CASE WHEN CUSTOMER_TYPE = \'RU\' THEN CUSTOMER_ID END) AS PLATFORM_RU FROM online_classified GROUP BY ORDER_DATE ), capsule_daily AS ( SELECT ORDER_DATE, CAPSULE, COUNT(DISTINCT CASE WHEN CUSTOMER_TYPE = \'NU\' THEN CUSTOMER_ID END) AS CAPSULE_NU, COUNT(DISTINCT CASE WHEN CUSTOMER_TYPE = \'RU\' THEN CUSTOMER_ID END) AS CAPSULE_RU FROM online_classified WHERE CAPSULE IS NOT NULL GROUP BY ORDER_DATE, CAPSULE ), offline_capsule_daily AS ( SELECT ORDER_DATE, CAPSULE, COUNT(DISTINCT CASE WHEN CUSTOMER_TYPE = \'NU\' THEN CUSTOMER_ID END) AS OFFLINE_CAPSULE_NU, COUNT(DISTINCT CASE WHEN CUSTOMER_TYPE = \'RU\' THEN CUSTOMER_ID END) AS OFFLINE_CAPSULE_RU FROM offline_classified WHERE CAPSULE IS NOT NULL GROUP BY ORDER_DATE, CAPSULE ), platform_monthly AS ( SELECT DATE_TRUNC( \'MONTH\', ORDER_DATE ) AS ORDER_MONTH_DATE, COUNT(DISTINCT CASE WHEN CUSTOMER_TYPE = \'NU\' THEN CUSTOMER_ID END) AS MONTHLY_PLATFORM_NU, COUNT(DISTINCT CASE WHEN CUSTOMER_TYPE = \'RU\' THEN CUSTOMER_ID END) AS MONTHLY_PLATFORM_RU FROM online_classified GROUP BY DATE_TRUNC( \'MONTH\', ORDER_DATE ) ), capsule_monthly AS ( SELECT DATE_TRUNC( \'MONTH\', ORDER_DATE ) AS ORDER_MONTH_DATE, CAPSULE, COUNT(DISTINCT CASE WHEN CUSTOMER_TYPE = \'NU\' THEN CUSTOMER_ID END) AS MONTHLY_CAPSULE_NU, COUNT(DISTINCT CASE WHEN CUSTOMER_TYPE = \'RU\' THEN CUSTOMER_ID END) AS MONTHLY_CAPSULE_RU FROM online_classified WHERE CAPSULE IS NOT NULL GROUP BY DATE_TRUNC( \'MONTH\', ORDER_DATE ), CAPSULE ), offline_capsule_monthly AS ( SELECT DATE_TRUNC( \'MONTH\', ORDER_DATE ) AS ORDER_MONTH_DATE, CAPSULE, COUNT(DISTINCT CASE WHEN CUSTOMER_TYPE = \'NU\' THEN CUSTOMER_ID END) AS MONTHLY_OFFLINE_CAPSULE_NU, COUNT(DISTINCT CASE WHEN CUSTOMER_TYPE = \'RU\' THEN CUSTOMER_ID END) AS MONTHLY_OFFLINE_CAPSULE_RU FROM offline_classified WHERE CAPSULE IS NOT NULL GROUP BY DATE_TRUNC( \'MONTH\', ORDER_DATE ), CAPSULE ) SELECT d.ORDER_DATE, DATE_TRUNC( \'MONTH\', d.ORDER_DATE ) AS ORDER_MONTH_DATE, TO_CHAR( DATE_TRUNC( \'MONTH\', d.ORDER_DATE ), \'MMMM YYYY\' ) AS ORDER_MONTH, d.CAPSULE, d.CAPSULE_NU AS DAILY_ONLINE_CAPSULE_NU, d.CAPSULE_RU AS DAILY_ONLINE_CAPSULE_RU, d.CAPSULE_NU + d.CAPSULE_RU AS DAILY_ONLINE_CAPSULE_TOTAL, ROUND( 100.0 * d.CAPSULE_NU / NULLIF( d.CAPSULE_NU + d.CAPSULE_RU, 0 ), 1 ) AS DAILY_ONLINE_CAPSULE_NU_PCT, ROUND( 100.0 * d.CAPSULE_RU / NULLIF( d.CAPSULE_NU + d.CAPSULE_RU, 0 ), 1 ) AS DAILY_ONLINE_CAPSULE_RU_PCT, od.OFFLINE_CAPSULE_NU, od.OFFLINE_CAPSULE_RU, od.OFFLINE_CAPSULE_NU + od.OFFLINE_CAPSULE_RU AS DAILY_OFFLINE_CAPSULE_TOTAL, ROUND( 100.0 * od.OFFLINE_CAPSULE_NU / NULLIF( od.OFFLINE_CAPSULE_NU + od.OFFLINE_CAPSULE_RU, 0 ), 1 ) AS DAILY_OFFLINE_CAPSULE_NU_PCT, ROUND( 100.0 * od.OFFLINE_CAPSULE_RU / NULLIF( od.OFFLINE_CAPSULE_NU + od.OFFLINE_CAPSULE_RU, 0 ), 1 ) AS DAILY_OFFLINE_CAPSULE_RU_PCT, pd.PLATFORM_NU AS DAILY_PLATFORM_NU, pd.PLATFORM_RU AS DAILY_PLATFORM_RU, pd.PLATFORM_NU + pd.PLATFORM_RU AS DAILY_PLATFORM_TOTAL, ROUND( 100.0 * pd.PLATFORM_NU / NULLIF( pd.PLATFORM_NU + pd.PLATFORM_RU, 0 ), 1 ) AS DAILY_PLATFORM_NU_PCT, ROUND( 100.0 * pd.PLATFORM_RU / NULLIF( pd.PLATFORM_NU + pd.PLATFORM_RU, 0 ), 1 ) AS DAILY_PLATFORM_RU_PCT, cm.MONTHLY_CAPSULE_NU, cm.MONTHLY_CAPSULE_RU, cm.MONTHLY_CAPSULE_NU + cm.MONTHLY_CAPSULE_RU AS MONTHLY_CAPSULE_TOTAL, ROUND( 100.0 * cm.MONTHLY_CAPSULE_NU / NULLIF( cm.MONTHLY_CAPSULE_NU + cm.MONTHLY_CAPSULE_RU, 0 ), 1 ) AS MONTHLY_CAPSULE_NU_PCT, ROUND( 100.0 * cm.MONTHLY_CAPSULE_RU / NULLIF( cm.MONTHLY_CAPSULE_NU + cm.MONTHLY_CAPSULE_RU, 0 ), 1 ) AS MONTHLY_CAPSULE_RU_PCT, om.MONTHLY_OFFLINE_CAPSULE_NU, om.MONTHLY_OFFLINE_CAPSULE_RU, om.MONTHLY_OFFLINE_CAPSULE_NU + om.MONTHLY_OFFLINE_CAPSULE_RU AS MONTHLY_OFFLINE_CAPSULE_TOTAL, ROUND( 100.0 * om.MONTHLY_OFFLINE_CAPSULE_NU / NULLIF( om.MONTHLY_OFFLINE_CAPSULE_NU + om.MONTHLY_OFFLINE_CAPSULE_RU, 0 ), 1 ) AS MONTHLY_OFFLINE_CAPSULE_NU_PCT, ROUND( 100.0 * om.MONTHLY_OFFLINE_CAPSULE_RU / NULLIF( om.MONTHLY_OFFLINE_CAPSULE_NU + om.MONTHLY_OFFLINE_CAPSULE_RU, 0 ), 1 ) AS MONTHLY_OFFLINE_CAPSULE_RU_PCT, pm.MONTHLY_PLATFORM_NU, pm.MONTHLY_PLATFORM_RU, pm.MONTHLY_PLATFORM_NU + pm.MONTHLY_PLATFORM_RU AS MONTHLY_PLATFORM_TOTAL, ROUND( 100.0 * pm.MONTHLY_PLATFORM_NU / NULLIF( pm.MONTHLY_PLATFORM_NU + pm.MONTHLY_PLATFORM_RU, 0 ), 1 ) AS MONTHLY_PLATFORM_NU_PCT, ROUND( 100.0 * pm.MONTHLY_PLATFORM_RU / NULLIF( pm.MONTHLY_PLATFORM_NU + pm.MONTHLY_PLATFORM_RU, 0 ), 1 ) AS MONTHLY_PLATFORM_RU_PCT, ROUND( ( 100.0 * cm.MONTHLY_CAPSULE_NU / NULLIF( cm.MONTHLY_CAPSULE_NU + cm.MONTHLY_CAPSULE_RU, 0 ) ) / NULLIF( 100.0 * pm.MONTHLY_PLATFORM_NU / NULLIF( pm.MONTHLY_PLATFORM_NU + pm.MONTHLY_PLATFORM_RU, 0 ), 0 ), 2 ) AS MONTHLY_NU_INDEX, ROUND( ( 100.0 * cm.MONTHLY_CAPSULE_RU / NULLIF( cm.MONTHLY_CAPSULE_NU + cm.MONTHLY_CAPSULE_RU, 0 ) ) / NULLIF( 100.0 * pm.MONTHLY_PLATFORM_RU / NULLIF( pm.MONTHLY_PLATFORM_NU + pm.MONTHLY_PLATFORM_RU, 0 ), 0 ), 2 ) AS MONTHLY_RU_INDEX FROM capsule_daily d LEFT JOIN platform_daily pd ON d.ORDER_DATE = pd.ORDER_DATE LEFT JOIN offline_capsule_daily od ON d.ORDER_DATE = od.ORDER_DATE AND LOWER(TRIM(d.CAPSULE)) = LOWER(TRIM(od.CAPSULE)) LEFT JOIN capsule_monthly cm ON DATE_TRUNC( \'MONTH\', d.ORDER_DATE ) = cm.ORDER_MONTH_DATE AND LOWER(TRIM(d.CAPSULE)) = LOWER(TRIM(cm.CAPSULE)) LEFT JOIN offline_capsule_monthly om ON DATE_TRUNC( \'MONTH\', d.ORDER_DATE ) = om.ORDER_MONTH_DATE AND LOWER(TRIM(d.CAPSULE)) = LOWER(TRIM(om.CAPSULE)) LEFT JOIN platform_monthly pm ON DATE_TRUNC( \'MONTH\', d.ORDER_DATE ) = pm.ORDER_MONTH_DATE ORDER BY d.ORDER_DATE DESC, d.CAPSULE;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            